type LocaleIndex = 0 | 1 | 2 | 3 | 4;
function buildTextMap(index: LocaleIndex): Record<SourceText<typeof en>, string> {
  return Object.fromEntries(Object.entries(translatedText).map(([source, values]) => [source, values[index]])) as Record<SourceText<typeof en>, string>;
}

function translateTree<T>(source: T, dictionary: Record<SourceText<typeof en>, string>): SameKeys<T> {
  if (typeof source === "string") return dictionary[source as SourceText<typeof en>] as SameKeys<T>;
  if (source && typeof source === "object") {
    return Object.fromEntries(Object.entries(source).map(([key, value]) => [key, translateTree(value, dictionary)])) as SameKeys<T>;
  }
  return source as SameKeys<T>;
}

const de = translateTree(en, buildTextMap(0));
const ruBase = translateTree(en, buildTextMap(1));
